const rows = $input.all().map(i => i.json);

const total = rows.length;
const ok = rows.filter(r => r['Status Geral'] === 'OK').length;
const pendente = rows.filter(r => r['Status Geral'] === 'PENDENTE').length;
const problema = total - ok - pendente; // REPROVADO + ERRO

const campos = ['Identificação','Ementa','Objetivos Geral','Objetivos Específicos','Conteúdo Programático','Metodologia','Proc. Avaliação','Cronograma','Avaliações','Horário Atendimento','Referências','Coerência'];

const cor = (s) => {
  if (s === 'OK') return '#22c55e';
  if (s === 'INCOMPLETO' || s === 'PENDENTE') return '#eab308';
  return '#ef4444'; // AUSENTE, REPROVADO, ERRO
};

const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const badge = (s) => `<span style="background:${cor(s)};color:#fff;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;white-space:nowrap">${esc(s) || '-'}</span>`;

const cards = rows.map(r => {
  const topicos = campos.map(c => {
    const obs = r[c + ' Obs'];
    return `<div style="border:1px solid #e5e7eb;border-left:4px solid ${cor(r[c])};border-radius:8px;padding:10px 12px;background:#fafafa">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
        <span style="font-size:13px;font-weight:600">${esc(c)}</span>
        ${badge(r[c])}
      </div>
      ${obs ? `<div style="font-size:12px;color:#6b7280;margin-top:6px">${esc(obs)}</div>` : ''}
    </div>`;
  }).join('');

  const nome = String(r['Arquivo'] || '').replace('2024-1 - ', '').replace('.pdf', '');
  const linkPdf = r['Link PDF']
    ? `<a href="${esc(r['Link PDF'])}" target="_blank" rel="noopener" style="font-size:13px;color:#2563eb;text-decoration:none;font-weight:600;white-space:nowrap" onclick="event.stopPropagation()">📄 Abrir PDF</a>`
    : '';

  return `<details style="background:#fff;border-radius:12px;box-shadow:0 1px 3px rgba(0,0,0,.1);margin-bottom:12px">
    <summary style="display:flex;align-items:center;gap:12px;padding:14px 16px;cursor:pointer;list-style:none">
      <span style="font-weight:600;flex:1">${esc(nome)}</span>
      ${badge(r['Status Geral'])}
      ${linkPdf}
      <span style="color:#9ca3af;font-size:12px">▼ detalhes</span>
    </summary>
    <div style="padding:0 16px 16px">
      ${r['Observação Geral'] ? `<p style="margin:0 0 12px;font-size:13px;color:#6b7280">${esc(r['Observação Geral'])}</p>` : ''}
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px">${topicos}</div>
    </div>
  </details>`;
}).join('');

const pct = (n) => total ? Math.round(n / total * 100) : 0;

const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Validação de Planos de Ensino</title>
<style>details summary::-webkit-details-marker{display:none}</style>
</head>
<body style="margin:0;font-family:system-ui,-apple-system,sans-serif;background:#f3f4f6;color:#111827">
<div style="max-width:1100px;margin:0 auto;padding:32px 16px">
  <h1 style="margin:0 0 4px">📋 Validação de Planos de Ensino</h1>
  <p style="margin:0 0 24px;color:#6b7280">Planos de Ensino 2024-1 · atualizado em ${new Date().toLocaleString('pt-BR')}</p>

  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px;margin-bottom:24px">
    <div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.1)">
      <div style="font-size:13px;color:#6b7280">Total de planos</div>
      <div style="font-size:32px;font-weight:700">${total}</div>
    </div>
    <div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.1);border-left:4px solid #22c55e">
      <div style="font-size:13px;color:#6b7280">Aprovados</div>
      <div style="font-size:32px;font-weight:700;color:#22c55e">${ok} <span style="font-size:14px;color:#9ca3af">(${pct(ok)}%)</span></div>
    </div>
    <div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.1);border-left:4px solid #eab308">
      <div style="font-size:13px;color:#6b7280">Pendentes</div>
      <div style="font-size:32px;font-weight:700;color:#eab308">${pendente} <span style="font-size:14px;color:#9ca3af">(${pct(pendente)}%)</span></div>
    </div>
    <div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.1);border-left:4px solid #ef4444">
      <div style="font-size:13px;color:#6b7280">Com problemas</div>
      <div style="font-size:32px;font-weight:700;color:#ef4444">${problema} <span style="font-size:14px;color:#9ca3af">(${pct(problema)}%)</span></div>
    </div>
  </div>

  ${cards}

  <p style="color:#9ca3af;font-size:12px;margin-top:16px">🟢 OK · 🟡 Incompleto/Pendente · 🔴 Ausente/Reprovado/Erro — clique em um plano para ver o detalhe de cada tópico</p>
</div>
</body>
</html>`;

return [{ json: { html } }];
